,p_triggering_region_id=>wwv_flow_imp.id(611341844866717146)
,p_triggering_element=>'QUANTITY1,QUANTITY2,WITHOUTDISCOUNTRATE,DISCOUNTPERCENTAGE,DISCOUNTRATE,RATE,AMOUNT'
