'                :MINIMUMWORKINGDAYS,',
'                :NOTICEPERIOD,',
'                :ISRATESLABWISE,',
'                :SLABTYPECODE,',
'                :BOQSERIALNO,',
'                :WBSCODE,',
'                :TASKSNO,',
'                :WITHOUTDISCOUNTRATE,',
'                :DISCOUNTPERCENTAGE,',
'                :DISCOUNTRATE',
'',
'            );',
