wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(611945199576861700)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get Document No'
,p_static_id=>'get-document-no'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    tModuleCode varchar2(30) := getModuleCodeForPageNo(:APP_PAGE_ID);',
'    tmp         number ;',
'begin',
'     if :P179_Tno is null then',
'        Select GlobalTno.NextVal into :P179_Tno From Dual;',
'     end if;',
'    ----',
'    if :P179_JOBORDERNO is null then',
'            SetDocNoNext(',
'					tModuleCode,',
'					:global_CompanyCode,',
'					:global_FinancialYearCode,',
'					:P179_LocationCode,',
'					:P179_DocTypeCode,',
'					NULL,',
'					TO_DATE(:P179_JOBORDERDATE, ''DD-MM-RRRR'')',
'				);',
'        :P179_JOBORDERNO := GetDocNo(',
'                    tModuleCode,',
'                    :global_CompanyCode,',
'                    :global_FinancialYearCode,',
'                    :P179_LocationCode,',
'                    :P179_DocTypeCode,',
'                    NULL,',
'                    TO_DATE(:P179_JOBORDERDATE, ''DD-MM-RRRR'')',
'                    );',
'    end if;',
'    ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>171558854325935176
);
